import XCTest
@testable import CounterpartKit

final class StarterProjectTests: XCTestCase {
    /// Nov 5: the bundled "Counterpart caliper card" was generated by an agent, never designed or print-tested, and
    /// was offered as something to print right now. Every starter is a real designer's model, imported from its page.
    func testCatalogHasOnlyRealDesignersModelsFromTheirPages() throws {
        XCTAssertEqual(StarterProject.all.map(\.id), ["scan-platform", "long-vernier-caliper"])
        XCTAssertTrue(StarterProject.all.allSatisfy { $0.source == "makerworld" && $0.url.host == "makerworld.com" })
        XCTAssertFalse(StarterProject.all.contains { $0.designer == "Counterpart" })
        XCTAssertTrue(StarterProject.all.allSatisfy { !$0.instructions.isEmpty && !$0.designer.isEmpty })
        XCTAssertNotNil(try XCTUnwrap(StarterProject.all.first { $0.id == "long-vernier-caliper" }).imageFile)
    }
}
